#include <bits/stdc++.h>
using namespace std;

bool canPut(const vector<char>& s, int p, char d) {
    return s[p] == 'X' || s[p] == '_' || s[p] == d;
}

void put(vector<char>& s, int p, char d) {
    if (s[p] == 'X') {
        for (auto& ch : s) {
            if (ch == 'X') ch = d;
        }
    } else {
        s[p] = d;
    }
}

int possible(vector<char> s) {
    int p = 1;
    if (s[0] == '0') {
        return 0;
    }
    if (s[0] == '_') {
        p *= 9;
    } else if (s[0] == 'X') {
        p *= 9;
        replace(s.begin(), s.end(), 'X', '1');
    }
    for (size_t i = 1; i < s.size(); ++i) {
        if (s[i] == '_') {
            p *= 10;
        } else if (s[i] == 'X') {
            p *= 10;
            replace(s.begin(), s.end(), 'X', '1');
        }
    }
    return p;
}

